package web

import (
	_ "embed"
	"encoding/json"
	"path"
	"strings"
	"sync"
)

// mimeJSON is the shared-mime-info data CMS reads through pyxdg,
// generated by mimedata/extract.py (see there).
//
//go:embed mimedata/mime.json
var mimeJSON []byte

type mimeTables struct {
	CasedLiterals map[string]string            `json:"cased_literals"`
	Literals      map[string]string            `json:"literals"`
	CasedExts     map[string]string            `json:"cased_exts"`
	Exts          map[string]string            `json:"exts"`
	Globs         [][3]any                     `json:"globs"`
	Aliases       map[string]string            `json:"aliases"`
	Icons         map[string]string            `json:"icons"`
	Comments      map[string]map[string]string `json:"comments"`

	globs []mimeGlob
}

type mimeGlob struct {
	pattern string
	cased   bool
	mime    string
}

var mimeData = sync.OnceValue(func() *mimeTables {
	var t mimeTables
	if err := json.Unmarshal(mimeJSON, &t); err != nil {
		panic("web: mimedata/mime.json: " + err.Error())
	}
	for _, g := range t.Globs {
		p, _ := g[0].(string)
		cased, _ := g[1].(bool)
		m, _ := g[2].(string)
		// fnmatch's [!...] is path.Match's [^...].
		p = strings.ReplaceAll(p, "[!", "[^")
		if !cased {
			p = strings.ToLower(p)
		}
		t.globs = append(t.globs, mimeGlob{pattern: p, cased: cased, mime: m})
	}
	return &t
})

// MimeType guesses the MIME type of a file from its name, as CMS's
// get_type_for_file_name (pyxdg over shared-mime-info): literal names
// first, then the extensions from the longest ("tar.gz") to the shortest,
// case-sensitive ones before the others, then the remaining globs. It
// returns "" when nothing matches (CMS None: the handlers then send
// application/octet-stream and the pages show the "unknown" icon).
func MimeType(filename string) string {
	t := mimeData()
	leaf := filename
	if i := strings.LastIndexByte(leaf, '/'); i >= 0 {
		leaf = leaf[i+1:]
	}
	if m, ok := t.CasedLiterals[leaf]; ok {
		return m
	}
	lleaf := strings.ToLower(leaf)
	if m, ok := t.Literals[lleaf]; ok {
		return m
	}
	for ext := leaf; ; {
		i := strings.IndexByte(ext, '.')
		if i < 0 {
			break
		}
		ext = ext[i+1:]
		if m, ok := t.CasedExts[ext]; ok {
			return m
		}
	}
	for ext := lleaf; ; {
		i := strings.IndexByte(ext, '.')
		if i < 0 {
			break
		}
		ext = ext[i+1:]
		if m, ok := t.Exts[ext]; ok {
			return m
		}
	}
	for _, g := range t.globs {
		name := leaf
		if !g.cased {
			name = lleaf
		}
		if ok, _ := path.Match(g.pattern, name); ok {
			return g.mime
		}
	}
	return ""
}

// canonicalMime resolves an alias ("application/x-pdf").
func canonicalMime(m string) string {
	if c, ok := mimeData().Aliases[m]; ok {
		return c
	}
	return m
}

// MimeIcon returns the generic icon of a MIME type (CMS
// get_icon_for_type): the pages show static/img/mimetypes/<icon>.png.
// Types without one get "<media>-x-generic", as in CMS.
func MimeIcon(mimetype string) string {
	m := canonicalMime(mimetype)
	if icon, ok := mimeData().Icons[m]; ok {
		return icon
	}
	media, _, _ := strings.Cut(m, "/")
	return media + "-x-generic"
}

// MimeComment names a MIME type in the language with the given CMS
// identifier ("es", "zh-Hant-TW"), as Translation.translate_mimetype:
// the comment of shared-mime-info in that language, its base language,
// or English; an unknown type is named by itself.
func MimeComment(mimetype, langID string) string {
	m := canonicalMime(mimetype)
	c, ok := mimeData().Comments[m]
	if !ok {
		return m
	}
	if s, ok := c[langID]; ok {
		return s
	}
	if base, _, found := strings.Cut(langID, "-"); found {
		if s, ok := c[base]; ok {
			return s
		}
	}
	return c[""]
}
